def interval_merges(split, n):
    operations = []
    stack = [[0, n, False]]
    while len(stack) > 0:
        frame = stack.pop()
        left = frame[0]
        right = frame[1]
        if right - left > 1:
            middle = split[left][right]
            if frame[2]:
                operations.append([left, middle, right])
            else:
                stack.append([left, right, True])
                stack.append([middle, right, False])
                stack.append([left, middle, False])
    return operations

